CREATE TABLE IF NOT EXISTS `expenses` ( `id` text PRIMARY KEY NOT NULL, `event_id` text NOT NULL, `title` text NOT NULL, `amount` integer NOT NULL, `payer_id` text NOT NULL, `participant_ids` text NOT NULL, `author_id` text NOT NULL, `created_at` integer NOT NULL, FOREIGN KEY (`event_id`) REFERENCES `gatherings`(`id`) ON UPDATE no action ON DELETE cascade ); CREATE TABLE IF NOT EXISTS `gatherings` ( `id` text PRIMARY KEY NOT NULL, `title` text NOT NULL, `kind` text NOT NULL, `description` text DEFAULT '' NOT NULL, `budget` integer DEFAULT 0 NOT NULL, `final_time_id` text, `final_place_id` text, `created_at` integer NOT NULL ); CREATE TABLE IF NOT EXISTS `members` ( `id` text PRIMARY KEY NOT NULL, `event_id` text NOT NULL, `name` text NOT NULL, `role` text DEFAULT 'guest' NOT NULL, `token_hash` text NOT NULL, `created_at` integer NOT NULL, `attendance` text DEFAULT 'pending' NOT NULL, FOREIGN KEY (`event_id`) REFERENCES `gatherings`(`id`) ON UPDATE no action ON DELETE cascade ); CREATE INDEX IF NOT EXISTS `members_event_idx` ON `members` (`event_id`); CREATE TABLE IF NOT EXISTS `options` ( `id` text PRIMARY KEY NOT NULL, `event_id` text NOT NULL, `kind` text NOT NULL, `label` text DEFAULT '' NOT NULL, `date` text DEFAULT '' NOT NULL, `time` text DEFAULT '' NOT NULL, `address` text DEFAULT '' NOT NULL, `url` text DEFAULT '' NOT NULL, `created_at` integer NOT NULL, FOREIGN KEY (`event_id`) REFERENCES `gatherings`(`id`) ON UPDATE no action ON DELETE cascade ); CREATE TABLE IF NOT EXISTS `rate_limits` ( `key` text PRIMARY KEY NOT NULL, `count` integer NOT NULL, `expires` integer NOT NULL ); CREATE TABLE IF NOT EXISTS `tasks` ( `id` text PRIMARY KEY NOT NULL, `event_id` text NOT NULL, `title` text NOT NULL, `quantity` text DEFAULT '' NOT NULL, `assignee_id` text, `done` integer DEFAULT 0 NOT NULL, `author_id` text NOT NULL, `created_at` integer NOT NULL, FOREIGN KEY (`event_id`) REFERENCES `gatherings`(`id`) ON UPDATE no action ON DELETE cascade, FOREIGN KEY (`assignee_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE set null ); CREATE TABLE IF NOT EXISTS `votes` ( `option_id` text NOT NULL, `member_id` text NOT NULL, `value` text NOT NULL, PRIMARY KEY(`option_id`, `member_id`), FOREIGN KEY (`option_id`) REFERENCES `options`(`id`) ON UPDATE no action ON DELETE cascade, FOREIGN KEY (`member_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE cascade ); CREATE TABLE IF NOT EXISTS `comments` ( `id` text PRIMARY KEY NOT NULL, `event_id` text NOT NULL, `author_id` text NOT NULL, `topic` text DEFAULT 'general' NOT NULL, `body` text NOT NULL, `created_at` integer NOT NULL, FOREIGN KEY (`event_id`) REFERENCES `gatherings`(`id`) ON UPDATE no action ON DELETE cascade, FOREIGN KEY (`author_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE cascade ); CREATE INDEX IF NOT EXISTS `comments_event_idx` ON `comments` (`event_id`); SELECT (SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('gatherings','members','options','votes','tasks','expenses','comments','rate_limits')) AS ready_tables, (SELECT COUNT(*) FROM pragma_table_info('members') WHERE name='attendance') AS attendance_ready;
